const std = @import("std");
const regex = @import("regex");
pub fn main() !void {
    var re = try regex.Regex.compileWithFlags(std.heap.page_allocator, "(?!.+X)", .{.ecmascript=true});
    defer re.deinit();
    re.backtrack_engine.?.max_steps = 25;
    const input = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaX";
    const hit = try re.find(input);
    if (hit) |r| {var m = r;defer m.deinit(std.heap.page_allocator);std.debug.print("MATCH {d}:{d} steps={d} limit={d}\n", .{m.start,m.end,re.backtrack_engine.?.step_count,re.backtrack_engine.?.max_steps});} else std.debug.print("NO MATCH steps={d}\n", .{re.backtrack_engine.?.step_count});
}

