const std = @import("std");
const regex = @import("regex");
fn walk(node: anytype, source: []const u8, depth: usize) anyerror!void {
    var r = try regex.analyzePattern(std.heap.page_allocator, node);
    defer r.deinit(std.heap.page_allocator);
    var critical = false;
    for (r.issues) |issue| {
        if (std.mem.startsWith(u8, issue, "CRITICAL:")) critical = true;
    }
    if (critical and (node.node_type == .star or node.node_type == .plus or node.node_type == .optional or node.node_type == .repeat)) {
        std.debug.print("QUANT depth={d} type={s} span={d}:{d} risk={s} factor={d}\n", .{depth, @tagName(node.node_type), node.span.start, node.span.end, @tagName(r.risk_level), r.explosion_factor});
        for (r.issues) |issue| std.debug.print("  {s}\n", .{issue});
    }
    switch (node.node_type) {
        .star => try walk(node.data.star.child, source, depth + 1),
        .plus => try walk(node.data.plus.child, source, depth + 1),
        .optional => try walk(node.data.optional.child, source, depth + 1),
        .repeat => try walk(node.data.repeat.child, source, depth + 1),
        .group => try walk(node.data.group.child, source, depth + 1),
        .lookahead => try walk(node.data.lookahead.child, source, depth + 1),
        .lookbehind => try walk(node.data.lookbehind.child, source, depth + 1),
        .concat => {try walk(node.data.concat.left, source, depth + 1);try walk(node.data.concat.right, source, depth + 1);},
        .alternation => {try walk(node.data.alternation.left, source, depth + 1);try walk(node.data.alternation.right, source, depth + 1);},
        else => {},
    }
}
pub fn main(init: std.process.Init) !void {
    const a = std.heap.page_allocator;
    const io = std.Io.Threaded.global_single_threaded.io();
    var args = try std.process.Args.Iterator.initAllocator(init.minimal.args, a);
    defer args.deinit();
    _ = args.next();
    const source = try std.Io.Dir.cwd().readFileAlloc(io, args.next().?, a, .limited(1024 * 1024));
    defer a.free(source);
    var p = try regex.parser.Parser.init(a, source);
    p.ecmascript = true;
    var tree = try p.parse();defer tree.deinit();
    try walk(tree.root, source, 0);
}
